Aqui está o script SQL completo para configurar o seu banco de dados no Supabase.

Você deve copiar e colar este código no **SQL Editor** do painel do Supabase e clicar em "Run".

Isso criará todas as tabelas necessárias (`profiles`, `businesses`, `posts`, `items`, `stock_movements`, `appointments`) com as colunas e tipos corretos para funcionar com o seu código React existente.

```sql
-- 1. Habilitar extensão para gerar IDs únicos (UUID)
create extension if not exists "uuid-ossp";

-- 2. Tabela de Perfis (Vinculada aos usuários do Supabase Auth)
create table public.profiles (
  id uuid references auth.users on delete cascade not null primary key,
  name text,
  email text,
  profile_pic_url text
);

-- 3. Tabela de Negócios (Businesses)
create table public.businesses (
  id uuid default uuid_generate_v4() primary key,
  owner_id uuid references public.profiles(id) on delete cascade not null,
  name text not null,
  category text not null,
  profile_pic_url text,
  country text,
  city text,
  neighborhood text,
  opening_hours text,
  open_days text,
  contact text,
  description text,
  created_at timestamptz default now()
);

-- 4. Tabela de Posts (Publicações no feed)
create table public.posts (
  id uuid default uuid_generate_v4() primary key,
  business_id uuid references public.businesses(id) on delete cascade not null,
  title text,
  description text,
  image_urls text[], -- Array de textos para múltiplas imagens
  created_at timestamptz default now()
);

-- 5. Tabela de Itens (Catálogo de Produtos/Serviços)
create table public.items (
  id uuid default uuid_generate_v4() primary key,
  business_id uuid references public.businesses(id) on delete cascade not null,
  name text not null,
  description text,
  image_urls text[],
  tags text[],
  quantity int default 0,
  price float default 0,
  created_at timestamptz default now()
);

-- 6. Tabela de Movimentações de Estoque
create table public.stock_movements (
  id uuid default uuid_generate_v4() primary key,
  item_id uuid references public.items(id) on delete cascade not null,
  business_id uuid references public.businesses(id) on delete cascade not null,
  type text check (type in ('entrada', 'saida')),
  quantity int not null,
  created_at timestamptz default now()
);

-- 7. Tabela de Agendamentos (Appointments)
create table public.appointments (
  id uuid default uuid_generate_v4() primary key,
  business_id uuid references public.businesses(id) on delete cascade not null,
  customer_name text,
  customer_contact text,
  service_name text,
  date text,
  time text,
  status text default 'pendente',
  created_at timestamptz default now()
);

-- 8. Configuração de Segurança (Row Level Security - RLS)
-- Isso permite que o frontend acesse os dados publicamente onde necessário, mas restrinja edições.

-- Habilitar RLS em todas as tabelas
alter table public.profiles enable row level security;
alter table public.businesses enable row level security;
alter table public.posts enable row level security;
alter table public.items enable row level security;
alter table public.stock_movements enable row level security;
alter table public.appointments enable row level security;

-- POLÍTICAS DE ACESSO (Simplificadas para funcionar com o App)

-- Perfis: Leitura pública, criação/edição apenas pelo dono
create policy "Perfis são visíveis publicamente" on public.profiles for select using (true);
create policy "Usuários podem inserir seu próprio perfil" on public.profiles for insert with check (auth.uid() = id);
create policy "Usuários podem atualizar seu próprio perfil" on public.profiles for update using (auth.uid() = id);

-- Negócios: Leitura pública, criação/edição apenas autenticado (logica simplificada)
create policy "Negócios são visíveis publicamente" on public.businesses for select using (true);
create policy "Usuários autenticados podem criar negócios" on public.businesses for insert with check (auth.role() = 'authenticated');
create policy "Donos podem atualizar seus negócios" on public.businesses for update using (auth.uid() = owner_id);

-- Posts e Itens: Leitura pública, Escrita autenticada
create policy "Posts públicos" on public.posts for select using (true);
create policy "Criar/Editar Posts" on public.posts for all using (auth.role() = 'authenticated');

create policy "Itens públicos" on public.items for select using (true);
create policy "Criar/Editar Itens" on public.items for all using (auth.role() = 'authenticated');

-- Estoque: Apenas autenticado vê e edita
create policy "Movimentação de estoque" on public.stock_movements for all using (auth.role() = 'authenticated');

-- Agendamentos:
create policy "Ver agendamentos" on public.appointments for select using (true);
create policy "Criar agendamentos (Público)" on public.appointments for insert with check (true);
create policy "Atualizar agendamentos (Donos)" on public.appointments for update using (auth.role() = 'authenticated');
```

### Configurações Adicionais (Storage - Imagens)

O seu app usa URLs base64 no momento para facilitar, mas se quiser usar o Supabase Storage no futuro, você precisará criar um "Bucket" chamado `images` no menu Storage e definir as políticas para "Public". Por enquanto, o código atual converte imagens para Base64 (string longa), o que funciona bem para testes, mas para produção recomenda-se usar o Supabase Storage para não pesar o banco de dados.

O código React atual (`utils/file.ts`) converte para Base64, então **não precisa mudar nada** no código, apenas rodar o SQL acima e o app vai funcionar e salvar as imagens como texto no banco de dados.

